#!/usr/bin/env node

/**
 * Verify a sealed template-status-mapping smoke-evidence bundle without
 * touching the running stack, the database, the network, or the wider
 * repository.
 *
 * The bundle is self-describing and is generated by
 * `capture-template-status-mapping-smoke-evidence.mjs`. A reviewer runs one
 * bounded command against the bundle directory:
 *
 *   node scripts/verify-template-status-mapping-smoke-evidence.mjs <bundle-dir>
 *   node <bundle-dir>/verify-evidence.mjs <bundle-dir>   # sealed identical copy
 *
 * What the bundle must prove, per claim:
 *
 *   - HEAD-tied provenance: `manifest.json` records the exact `git rev-parse
 *     HEAD` SHA, branch, `git status --porcelain` (including the known-dirty
 *     `package-lock.json`), a canonical timestamp, and environment identity
 *     (server URL, DB host/port/database) — so every artifact is attributable
 *     to a specific commit and environment.
 *   - Raw query evidence: each assertion step writes its exact SQL, the
 *     redacted psql invocation, and the unmodified psql output, alongside a
 *     machine-readable assertions record the verifier re-checks.
 *   - Screenshot slots: the nine named UI screenshots are enumerated with
 *     per-file SHA-256 checksums so a screenshot can be neither swapped nor
 *     silently omitted. A slot may be `PENDING` only when it carries an exact
 *     capture instruction.
 *   - Restoration: the seeded template is restored byte-for-byte (recomputed
 *     against the pre-mutation baseline) and the log scans are shown raw —
 *     an empty scan is displayed, not asserted.
 *
 * The verifier is intentionally self-contained (Node built-ins only) so the
 * sealed copy inside the bundle runs anywhere a Node runtime exists. The
 * capture harness imports `verifyBundle` at sealing time and refuses to seal a
 * bundle that does not verify, which keeps the two files from drifting apart.
 *
 * Exit codes: 0 when every claim passes, 1 on any mismatch, 2 on usage errors.
 */

import { createHash } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';

export const VERIFIER_COPY_FILE = 'verify-evidence.mjs';
export const RUN_FILE = '00-workflow-run.json';
export const GIT_HEAD_FILE = '01-git-head.txt';
export const GIT_STATUS_FILE = '01-git-status.txt';
export const ENVIRONMENT_FILE = '01-environment.json';
export const SEED_SQL_FILE = '10-fixture-seed.sql';
export const MANIFEST_FILE = 'manifest.json';
export const README_FILE = 'README.md';
export const CHECKSUM_FILE = 'SHA256SUMS';
export const SCREENSHOT_NOTES_FILE = '91-screenshot-slots.json';
export const ARTIFACTS_FILE = '92-artifacts.json';
export const MANUAL_ACTIONS_FILE = '93-manual-actions.json';
export const DEV_SERVER_SCAN_JSON = '40-dev-server-log-scan.json';
export const DEV_SERVER_SCAN_TXT = '40-dev-server-log-scan.txt';
export const CONSOLE_FILE = '41-browser-console.json';
export const NETWORK_FILE = '42-browser-network.json';
export const REDACTION_PLACEHOLDER = '<redacted: server/.env.local DB_PASSWORD_SERVER>';

export const EVIDENCE_STEPS = {
  before: { json: '10-fixture-before.json', txt: '10-fixture-before-queries.txt' },
  'after-apply': { json: '20-after-apply.json', txt: '20-after-apply-queries.txt' },
  'after-replace': { json: '21-after-replace.json', txt: '21-after-replace-queries.txt' },
  'after-global-reject': { json: '22-after-global-reject.json', txt: '22-after-global-reject-queries.txt' },
  restore: { json: '30-restoration.json', txt: '30-restoration-queries.txt' },
};

