const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const COMMIT_PATTERN = /^[0-9a-f]{40}$/i;

function sha256File(filePath) {
  return createHash('sha256').update(fs.readFileSync(filePath)).digest('hex');
}

function describeValue(value) {
  const serialized = JSON.stringify(value);
  if (serialized === undefined) {
    return String(value);
  }
  return serialized.length > 200 ? `${serialized.slice(0, 200)}…` : serialized;
}

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

/**
 * Bundle evaluation context with a strict path guard, cached JSON reads, and
 * identity/checksum helpers so every referenced artifact is inside the bundle.
 */
export function createContext(evidenceDirectory, { timeoutMs = 60_000 } = {}) {
  const directory = path.resolve(evidenceDirectory);
  if (!fs.existsSync(directory) || !fs.statSync(directory).isDirectory()) {
    throw new Error(`Evidence directory not found: ${directory}`);
  }
  const startedAt = Date.now();
  const jsonCache = new Map();
  const context = {
    directory,
    checkDeadline() {
      if (Date.now() - startedAt >= timeoutMs) {
        throw new Error(`Verification exceeded its ${timeoutMs} ms deadline`);
      }
    },
    filePath(name) {
      const resolved = path.resolve(directory, name);
      const relative = path.relative(directory, resolved);
      if (relative === '..' || relative.startsWith(`..${path.sep}`) || path.isAbsolute(relative)) {
        throw new Error(`Evidence file reference escapes the bundle: ${name}`);
      }
      return resolved;
    },
    readJson(name) {
      if (!jsonCache.has(name)) {
        const filePath = context.filePath(name);
        if (!fs.existsSync(filePath)) {
          throw new Error(`Required evidence file is missing: ${name}`);
        }
        let parsed;
        try {
          parsed = JSON.parse(fs.readFileSync(filePath, 'utf8'));
        } catch (error) {
          throw new Error(`Evidence file is not valid JSON: ${name} (${error instanceof Error ? error.message : String(error)})`);
        }
        jsonCache.set(name, parsed);
      }
      return jsonCache.get(name);
    },
    hashFile(name) {
      context.checkDeadline();
      return sha256File(context.filePath(name));
    },
    fileExists(name) {
      return fs.existsSync(context.filePath(name)) && fs.statSync(context.filePath(name)).isFile();
    },
  };
  return context;
}

function validateRunRecord(context) {
  const failures = [];
  const run = context.readJson(RUN_FILE);
  if (!isObject(run)) {
    return [`${RUN_FILE} is not a JSON object`];
  }
  if (!UUID_PATTERN.test(run.workflowRunId || '')) {
    failures.push(`${RUN_FILE} does not record a workflow run UUID`);
  }
  const startedAt = new Date(run.startedAt);
  if (typeof run.startedAt !== 'string'
    || Number.isNaN(startedAt.valueOf())
    || startedAt.toISOString() !== run.startedAt) {
    failures.push(`${RUN_FILE} startedAt is not a canonical ISO timestamp`);
  }
  if (typeof run.appUrl !== 'string' || !run.appUrl.startsWith('http')) {
    failures.push(`${RUN_FILE} does not record the application URL`);
  }
  if (!UUID_PATTERN.test(run.tenantId || '')) {
    failures.push(`${RUN_FILE} does not record the tenant UUID`);
  }
  if (!UUID_PATTERN.test(run.seedTemplateId || '')) {
    failures.push(`${RUN_FILE} does not record the seed template UUID`);
  }
  if (!UUID_PATTERN.test(run.knownMappingId || '')) {
    failures.push(`${RUN_FILE} does not record the known mapping UUID`);
  }
  if (!Number.isInteger(run.expectedTaskCount) || run.expectedTaskCount < 1) {
    failures.push(`${RUN_FILE} does not record a positive expected task count`);
  }
  return failures;
}

function validateManifest(context) {
  const failures = [];
  const manifest = context.readJson(MANIFEST_FILE);
  if (!isObject(manifest)) {
    return [`${MANIFEST_FILE} is not a JSON object`];
  }
  const run = context.readJson(RUN_FILE);
  if (manifest.workflowRunId !== run.workflowRunId) {
    failures.push(`${MANIFEST_FILE} records a different workflow run`);
  }
  if (!COMMIT_PATTERN.test(manifest.headSha || '')) {
    failures.push(`${MANIFEST_FILE} does not record a 40-hex HEAD SHA`);
  }
  if (typeof manifest.branch !== 'string' || manifest.branch.trim() === '') {
    failures.push(`${MANIFEST_FILE} does not record the git branch`);
  }
  const gitStatus = manifest.gitStatus;
  const gitStatusText = Array.isArray(gitStatus) ? gitStatus.join('\n') : String(gitStatus || '');
  if (typeof gitStatusText !== 'string' || !gitStatusText.includes('package-lock.json')) {
    failures.push(`${MANIFEST_FILE} git status does not record the known-dirty package-lock.json`);
  }
  const timestamp = new Date(manifest.timestamp);
  if (typeof manifest.timestamp !== 'string'
    || Number.isNaN(timestamp.valueOf())
    || timestamp.toISOString() !== manifest.timestamp) {
    failures.push(`${MANIFEST_FILE} timestamp is not a canonical ISO timestamp`);
  }
  if (timestamp < new Date(run.startedAt)) {
    failures.push(`${MANIFEST_FILE} timestamp predates the smoke run`);
  }
  const environment = manifest.environment;
  if (!isObject(environment)
    || typeof environment.serverUrl !== 'string' || !environment.serverUrl.startsWith('http')
    || typeof environment.dbHost !== 'string' || environment.dbHost.trim() === ''
    || !Number.isInteger(environment.dbPort) || environment.dbPort < 1
    || typeof environment.dbName !== 'string' || environment.dbName.trim() === '') {
    failures.push(`${MANIFEST_FILE} environment identity is incomplete`);
  }
  if (typeof environment.credentialsDerivation !== 'string'
    || !environment.credentialsDerivation.includes('server/.env.local')) {
    failures.push(`${MANIFEST_FILE} environment must document where DB credentials are derived from`);
  }
  if (!Array.isArray(manifest.stepLog) || manifest.stepLog.length === 0) {
    failures.push(`${MANIFEST_FILE} does not record the step log`);
  }
  if (!isObject(manifest.screenshotSlots) || !Array.isArray(manifest.screenshotSlots.slots)) {
    failures.push(`${MANIFEST_FILE} does not enumerate the screenshot slots`);
  }
  return failures;
}

function listFilesRecursive(directory) {
  const walk = (dir) => {
    const out = [];
    for (const name of fs.readdirSync(dir)) {
      const full = path.join(dir, name);
      const rel = path.relative(directory, full);
      if (fs.statSync(full).isDirectory()) {
        out.push(...walk(full));
      } else {
        out.push(rel);
      }
    }
    return out;
  };
  return walk(directory).sort((left, right) => left.localeCompare(right));
}

function validateChecksumCoverage(context) {
  const failures = [];
  const actualFiles = listFilesRecursive(context.directory);

  const checksumPath = context.filePath(CHECKSUM_FILE);
  if (!fs.existsSync(checksumPath)) {
    return [`${CHECKSUM_FILE} is missing`];
  }
  const listed = new Map();
  for (const line of fs.readFileSync(checksumPath, 'utf8').split('\n').filter((line) => line !== '')) {
    const match = /^([0-9a-f]{64}) {2}(.+)$/.exec(line);
    if (!match) {
      failures.push(`${CHECKSUM_FILE} has a malformed line: ${line}`);
      continue;
    }
    listed.set(match[2], match[1]);
  }
  const expectedListed = actualFiles.filter((name) => name !== CHECKSUM_FILE);
  const listedNames = [...listed.keys()].sort((a, b) => a.localeCompare(b));
  if (JSON.stringify(listedNames) !== JSON.stringify(expectedListed)) {
    failures.push(
      `${CHECKSUM_FILE} does not cover exactly the bundle files (listed ${listed.size}, present ${expectedListed.length})`
    );
  }
  for (const [name, expectedHash] of listed) {
    if (!expectedListed.includes(name)) {
      continue;
    }
    if (context.hashFile(name) !== expectedHash) {
      failures.push(`${name} does not match its ${CHECKSUM_FILE} entry`);
    }
  }
  return failures;
}

function validateEvidenceAssertions(context) {
  const failures = [];
  for (const [stepName, { json, txt }] of Object.entries(EVIDENCE_STEPS)) {
    const record = context.readJson(json);
    if (!isObject(record)) {
      failures.push(`${json} is not a JSON object`);
      continue;
    }
    if (record.step !== stepName) {
      failures.push(`${json} declares the wrong step (${record.step})`);
    }
    if (typeof record.rawOutputFile !== 'string' || record.rawOutputFile !== txt) {
      failures.push(`${json} does not name its raw output file ${txt}`);
    }
    if (!context.fileExists(txt)) {
      failures.push(`${json} raw output file ${txt} is missing`);
    }
    if (!Array.isArray(record.assertions) || record.assertions.length === 0) {
      failures.push(`${json} does not record any assertions`);
      continue;
    }
    for (const assertion of record.assertions) {
      if (!isObject(assertion) || typeof assertion.id !== 'string' || assertion.id.trim() === '') {
        failures.push(`${json} contains a malformed assertion`);
        continue;
      }
      if (assertion.passed !== true) {
        const detail = assertion.detail ? ` — ${assertion.detail}` : '';
        failures.push(`${json} assertion ${assertion.id} did not pass${detail}`);
      }
    }
  }
  return failures;
}

/**
 * Recomputed checks that cross files and prove the acceptance criteria, not
 * just self-reported assertions.
 */
function validateCrossFileClaims(context) {
  const failures = [];
  const run = context.readJson(RUN_FILE);
  const before = context.readJson(EVIDENCE_STEPS.before.json);
  const afterApply = context.readJson(EVIDENCE_STEPS['after-apply'].json);
  const afterReplace = context.readJson(EVIDENCE_STEPS['after-replace'].json);
  const afterGlobalReject = context.readJson(EVIDENCE_STEPS['after-global-reject'].json);
  const restoration = context.readJson(EVIDENCE_STEPS.restore.json);

  const beforeData = before.structuredData || {};
  const afterApplyData = afterApply.structuredData || {};
  const afterReplaceData = afterReplace.structuredData || {};
  const afterGlobalRejectData = afterGlobalReject.structuredData || {};
  const restorationData = restoration.structuredData || {};

  if (!Array.isArray(beforeData.seedTemplateOriginal)
    || beforeData.seedTemplateOriginal.length === 0) {
    failures.push('before step does not capture the seed template original mapping rows');
  }
  if (!Number.isInteger(afterReplaceData.taskAssignmentCountAfter)
    || afterReplaceData.taskAssignmentCountAfter < 1) {
    failures.push('after-replace step does not capture the task assignments after replacement');
  }
  if (beforeData.taskAssignmentCountBefore !== run.expectedTaskCount) {
    failures.push(
      `task assignments before replacement: ${describeValue(beforeData.taskAssignmentCountBefore)}, expected ${run.expectedTaskCount}`
    );
  }
  if (afterReplaceData.taskAssignmentCountAfter !== run.expectedTaskCount) {
    failures.push(
      `task assignments after replacement: ${describeValue(afterReplaceData.taskAssignmentCountAfter)}, expected ${run.expectedTaskCount}`
    );
  }

  const standardRow = Array.isArray(afterApplyData.typedProjectMappings)
    ? afterApplyData.typedProjectMappings.find((row) => row.is_standard === true)
    : undefined;
  const tenantRow = Array.isArray(afterApplyData.typedProjectMappings)
    ? afterApplyData.typedProjectMappings.find((row) => row.is_standard === false)
    : undefined;
  if (!standardRow || !standardRow.standard_status_id || standardRow.status_id !== null) {
    failures.push('applied project lacks a standard project_status_mapping row (standard_status_id set, status_id null, is_standard true)');
  }
  if (!tenantRow || !tenantRow.status_id || tenantRow.standard_status_id !== null) {
    failures.push('applied project lacks a tenant/custom project_status_mapping row (status_id set, standard_status_id null, is_standard false)');
  }

  if (beforeData.unresolvedCountBroken !== 2) {
    failures.push(`broken fixture unresolved count: ${describeValue(beforeData.unresolvedCountBroken)}, expected 2`);
  }
  if (afterReplaceData.unresolvedCountAfterReplace !== 1) {
    failures.push(`unresolved count after one in-place replacement: ${describeValue(afterReplaceData.unresolvedCountAfterReplace)}, expected 1`);
  }

  if (!isObject(beforeData.deletionGuardTemplateUsage) || (beforeData.deletionGuardTemplateUsage.templateCount || 0) < 1) {
    failures.push('deletion guard: no template usage recorded for the referenced tenant status');
  }
  if (!isObject(beforeData.deletionGuardFkRestrict)
    || beforeData.deletionGuardFkRestrict.exitCode === 0
    || beforeData.deletionGuardFkRestrict.matched !== true) {
    failures.push('deletion guard: the FK RESTRICT delete attempt did not fail on project_template_status_mappings');
  }

  if (afterGlobalRejectData.projectCountAfter !== afterApplyData.projectCountAfterValidApply) {
    failures.push(
      `global apply must create zero projects: count before attempt ${describeValue(afterApplyData.projectCountAfterValidApply)} vs after ${describeValue(afterGlobalRejectData.projectCountAfter)}`
    );
  }
  if (afterGlobalRejectData.attemptedProjectCountAfter !== 0
    || afterApplyData.attemptedProjectCountBefore !== 0) {
    failures.push('global apply rejection must prove the attempted project was never created');
  }

  if (!Array.isArray(restorationData.seedTemplateAfterRestore)
    || JSON.stringify(restorationData.seedTemplateAfterRestore) !== JSON.stringify(beforeData.seedTemplateOriginal)) {
    failures.push('seed template was not restored exactly (recomputed against the original baseline)');
  }
  if (restorationData.taskAssignmentCountAfterRestore !== run.expectedTaskCount) {
    failures.push(`seed template task assignments after restore: ${describeValue(restorationData.taskAssignmentCountAfterRestore)}, expected ${run.expectedTaskCount}`);
  }

  return failures;
}

function validateScreenshotSlots(context) {
  const failures = [];
  const notes = context.readJson(SCREENSHOT_NOTES_FILE);
  const manifest = context.readJson(MANIFEST_FILE);
  if (!isObject(notes) || !Array.isArray(notes.slots)) {
    failures.push(`${SCREENSHOT_NOTES_FILE} does not enumerate slots`);
    return failures;
  }
  const declaredIds = notes.slots.map((slot) => slot.id);
  const requiredIds = SCREENSHOT_SLOTS.map((slot) => slot.id);
  if (JSON.stringify(declaredIds) !== JSON.stringify(requiredIds)) {
    failures.push(
      `${SCREENSHOT_NOTES_FILE} does not declare exactly the required slots`
      + ` (declared ${declaredIds.length}, required ${requiredIds.length})`
    );
    return failures;
  }
  if (!isObject(manifest.screenshotSlots)
    || manifest.screenshotSlots.workflowRunId !== context.readJson(RUN_FILE).workflowRunId) {
    failures.push(`${MANIFEST_FILE} screenshotSlots does not match the workflow run`);
  }
  const manifestSlotById = new Map(
    (manifest.screenshotSlots?.slots || []).map((slot) => [slot.id, slot])
  );

  for (const [index, slot] of notes.slots.entries()) {
    const template = SCREENSHOT_SLOTS[index];
    if (slot.file !== template.file) {
      failures.push(`slot ${slot.id} does not use the canonical file name ${template.file}`);
    }
    if (slot.status === 'complete') {
      if (!context.fileExists(slot.file)) {
        failures.push(`slot ${slot.id} is complete but ${slot.file} is missing`);
        continue;
      }
      if (typeof slot.url !== 'string' || !slot.url.startsWith('http')) {
        failures.push(`slot ${slot.id} is complete but records no URL`);
      }
      if (typeof slot.pageText !== 'string' || slot.pageText.trim() === '') {
        failures.push(`slot ${slot.id} is complete but records no captured page text`);
      }
      const capturedAt = new Date(slot.capturedAt);
      if (typeof slot.capturedAt !== 'string' || Number.isNaN(capturedAt.valueOf())) {
        failures.push(`slot ${slot.id} has an invalid capturedAt`);
      }
      const manifestSlot = manifestSlotById.get(slot.id);
      if (!manifestSlot || manifestSlot.status !== 'complete' || manifestSlot.sha256 !== context.hashFile(slot.file)) {
        failures.push(`slot ${slot.id} does not match its manifest checksum entry`);
      }
    } else if (slot.status === 'pending') {
      if (typeof slot.instructions !== 'string' || slot.instructions.trim() === '') {
        failures.push(`slot ${slot.id} is PENDING without an exact capture instruction`);
      }
    } else {
      failures.push(`slot ${slot.id} has an unknown status ${describeValue(slot.status)}`);
    }
  }
  return failures;
}

function validateLogScans(context) {
  const failures = [];
  const scan = context.readJson(DEV_SERVER_SCAN_JSON);
  if (!isObject(scan)
    || typeof scan.scanCommand !== 'string' || scan.scanCommand.trim() === ''
    || !context.fileExists(DEV_SERVER_SCAN_TXT)) {
    failures.push(`dev-server log scan must record its command and raw output (${DEV_SERVER_SCAN_JSON} / ${DEV_SERVER_SCAN_TXT})`);
  }
  if (!isObject(scan) || !Array.isArray(scan.scannedFor) || scan.scannedFor.length === 0) {
    failures.push('dev-server log scan must record the error patterns it scanned for');
  }
  if (!context.fileExists(CONSOLE_FILE)) {
    failures.push(`browser console capture (${CONSOLE_FILE}) is missing`);
  } else {
    const consoleCapture = context.readJson(CONSOLE_FILE);
    if (!isObject(consoleCapture) || !Array.isArray(consoleCapture.entries) || !Array.isArray(consoleCapture.errors)) {
      failures.push(`${CONSOLE_FILE} does not record browser console errors raw`);
    }
  }
  if (!context.fileExists(NETWORK_FILE)) {
    failures.push(`browser network capture (${NETWORK_FILE}) is missing`);
  } else {
    const networkCapture = context.readJson(NETWORK_FILE);
    if (!isObject(networkCapture) || !Array.isArray(networkCapture.failedRequests)) {
      failures.push(`${NETWORK_FILE} does not record failed network requests raw`);
    }
  }
  return failures;
}

function validateReadmeAndRedaction(context) {
  const failures = [];
  const readmePath = context.filePath(README_FILE);
  if (!context.fileExists(README_FILE)) {
    failures.push(`${README_FILE} is missing`);
    return failures;
  }
  const readme = fs.readFileSync(readmePath, 'utf8');
  for (const needle of ['server/.env.local', 'DB_PASSWORD_SERVER', '5472']) {
    if (!readme.includes(needle)) {
      failures.push(`${README_FILE} must document connection derivation including "${needle}"`);
    }
  }
  if (!readme.includes(REDACTION_PLACEHOLDER.split(' ')[0])) {
    failures.push(`${README_FILE} must document that secrets are redacted, never embedded`);
  }

  for (const entry of [DEV_SERVER_SCAN_JSON, GIT_HEAD_FILE]) {
    if (!context.fileExists(entry)) {
      continue;
    }
  }

  for (const { txt } of Object.values(EVIDENCE_STEPS)) {
    if (!context.fileExists(txt)) {
      continue;
    }
    const contents = fs.readFileSync(context.filePath(txt), 'utf8');
    const lines = contents.split('\n').filter((line) => line.startsWith('$ '));
    for (const line of lines) {
      if (line.includes('PGPASSWORD=') && !line.includes(REDACTION_PLACEHOLDER)) {
        failures.push(`${txt} records a psql invocation with a non-redacted PGPASSWORD`);
      }
    }
  }
  return failures;
}

export function verifyBundle(evidenceDirectory, options = {}) {
  const failures = [];
  const context = createContext(evidenceDirectory, options);
  const collectors = [
    validateRunRecord,
    validateManifest,
    validateChecksumCoverage,
    validateEvidenceAssertions,
    validateCrossFileClaims,
    validateScreenshotSlots,
    validateLogScans,
    validateReadmeAndRedaction,
  ];
  for (const collector of collectors) {
    let result;
    try {
      result = collector(context);
    } catch (error) {
      result = [error instanceof Error ? error.message : String(error)];
    }
    failures.push(...result);
  }

  const screenshotSlots = context.readJson(SCREENSHOT_NOTES_FILE).slots || [];
  const pendingSlots = screenshotSlots.filter((slot) => slot.status === 'pending');
  const summary = {
    bundleDigest: sha256File(context.filePath(CHECKSUM_FILE)),
    headSha: context.readJson(MANIFEST_FILE).headSha,
    screenshots: { total: screenshotSlots.length, complete: screenshotSlots.length - pendingSlots.length, pending: pendingSlots.length },
    pass: failures.length === 0,
  };
  return { ...summary, failures };
}

export function main(argv) {
  const args = argv.slice(2);
  const flags = [];
  for (const arg of args) {
    if (arg.startsWith('--timeout-ms=')) {
      flags.push(Number(arg.split('=')[1]));
    }
  }
  const positional = args.filter((arg) => !arg.startsWith('--'));
  if (positional.length !== 1) {
    process.stderr.write('Usage: node verify-template-status-mapping-smoke-evidence.mjs <bundle-dir> [--timeout-ms=<n>]\n');
    return 2;
  }
  const result = verifyBundle(positional[0], { timeoutMs: flags[0] || undefined });
  if (!result.pass) {
    process.stdout.write('VERDICT: FAIL\n');
    for (const failure of result.failures) {
      process.stdout.write(`  - ${failure}\n`);
    }
    process.stdout.write(`bundleDigest=${result.bundleDigest}\n`);
    return 1;
  }
  process.stdout.write('VERDICT: PASS\n');
  process.stdout.write(`headSha=${result.headSha}\n`);
  process.stdout.write(`screenshots=${result.screenshots.complete}/${result.screenshots.total} complete (${result.screenshots.pending} pending)\n`);
  process.stdout.write(`bundleDigest=${result.bundleDigest}\n`);
  return 0;
}

if (import.meta.url === pathToFileUrl(process.argv[1]).href) {
  process.exitCode = main(process.argv);
}

function pathToFileUrl(filePath) {
  return new URL(`file://${filePath}`);
}
